/* ==========================================================================
   views-xm-lib.js — Component & Widget Library for the Page & Experience Manager.
   Every component reads live ERP data through the same helpers the pages use and
   is gated by the same permissions. Nothing here posts, approves or edits data:
   actions and shortcuts open the existing workflows.
   ========================================================================== */

function xmAllowed(perm, a = A) {
  if (!perm || !a) return !perm;
  if (typeof perm === "function") { try { return !!perm(a); } catch { return false; } }
  return (Array.isArray(perm) ? perm : [perm]).some((p) => (p === "@employee" ? !!a.employee : can(a, p)));
}
const xmPermText = (perm) => (!perm ? "None (everyone)" : typeof perm === "function" ? "Decided by the page's own rules" : (Array.isArray(perm) ? perm : [perm]).map((p) => (p === "@employee" ? "an employee record" : p)).join(" or "));
function xmRangeDates(range) {
  const t = todayStr();
  if (range === "month") return [t.slice(0, 8) + "01", t];
  if (range === "quarter") { const m = +t.slice(5, 7); const qm = m - ((m - 1) % 3); return [`${t.slice(0, 5)}${String(qm).padStart(2, "0")}-01`, t]; }
  if (range === "year") return [t.slice(0, 5) + "01-01", t];
  if (range === "all") return ["0000-01-01", "9999-12-31"];
  return [addDays(t, -30), t];
}
const xmInRange = (d, r) => { if (!d) return false; const s = String(d).slice(0, 10); return s >= r[0] && s <= r[1]; };
/** the employees a scope covers, for the person looking */
function xmScopeEmps(scope, a = A) {
  const ids = scopeIds(S, a), me = a.employee;
  const emps = S.employees.filter((e) => ids.includes(e.companyId) && e.status !== "TERMINATED");
  switch (scope) {
    case "user": return me ? emps.filter((e) => e.id === me.id) : [];
    case "team": return me ? emps.filter((e) => e.managerId === me.id || e.id === me.id) : [];
    case "department": return me ? emps.filter((e) => e.departmentId === me.departmentId) : [];
    case "company": { const c = a.activeCompanyId || me?.companyId; return c ? emps.filter((e) => e.companyId === c) : emps; }
    default: return emps;
  }
}
const xmScopeText = (scope) => XM_SCOPES.find((s) => s[0] === scope)?.[1] || "Organization";
const xmCard = (title, body, right = "", cls = "") => `<section class="hcard ${cls}">${title ? `<div class="hcard-h"><h2>${esc(title)}</h2>${right}</div>` : ""}${body}</section>`;
const xmLink = (go, label) => `<button class="lnk" style="font-size:12.5px" data-go="${esc(go)}">${esc(label)}</button>`;
const xmEmptyMsg = (t) => `<p class="xm-empty">${esc(t)}</p>`;
const xmList = (rows) => (rows.length ? `<ul class="xm-list">${rows.map((r) => `<li><span style="min-width:0"><b>${esc(r.t)}</b>${r.s ? `<small>${esc(r.s)}</small>` : ""}</span>${r.r != null ? `<span class="num" style="white-space:nowrap">${esc(r.r)}</span>` : ""}</li>`).join("")}</ul>` : "");
const xmTiles = (tiles) => `<div class="xm-tiles">${tiles.map((t) => `<button class="stat" ${t.go ? `data-go="${esc(t.go)}"` : ""} style="text-align:left;font:inherit;cursor:${t.go ? "pointer" : "default"}"><div class="l">${esc(t.l)}</div><div class="v">${esc(t.v)}</div>${t.h ? `<div class="h hint">${esc(t.h)}</div>` : ""}</button>`).join("")}</div>`;
const xmBars = (items, fmt = (v) => String(v)) => { const max = Math.max(1, ...items.map((x) => x.v)); return items.length ? `<div class="xm-bars">${items.map((x, i) => `<div class="hbar"><span class="nm" title="${esc(x.label)}">${esc(x.label)}</span><span class="tr"><i style="width:${Math.round((x.v / max) * 100)}%;background:var(--c${(i % 6) + 1})"></i></span><span class="num" style="font-size:12px;min-width:64px;text-align:right">${esc(x.d || fmt(x.v))}</span></div>`).join("")}</div>` : xmEmptyMsg("Nothing to chart for this selection."); };
function xmLineSvg(labels, lines, fmt = (v) => String(v)) {
  const W = 520, H = 170, L = 44, R = 10, T = 12, B = 26;
  const all = lines.flatMap((l) => l.values); const max = Math.max(1, ...all), min = Math.min(0, ...all);
  const x = (i) => L + (i * (W - L - R)) / Math.max(1, labels.length - 1), y = (v) => T + (H - T - B) * (1 - (v - min) / (max - min || 1));
  const grid = [0, 0.5, 1].map((f) => { const v = min + (max - min) * f; return `<line x1="${L}" x2="${W - R}" y1="${y(v).toFixed(1)}" y2="${y(v).toFixed(1)}" stroke="var(--grid)" stroke-dasharray="3 3"/><text class="ax" x="${L - 4}" y="${(y(v) + 3).toFixed(1)}" text-anchor="end">${esc(fmt(v))}</text>`; }).join("");
  const paths = lines.map((l, li) => `<path class="${li ? "l2" : "l"}" d="${l.values.map((v, i) => `${i ? "L" : "M"}${x(i).toFixed(1)},${y(v).toFixed(1)}`).join(" ")}"/>${l.values.map((v, i) => `<circle class="dot" cx="${x(i).toFixed(1)}" cy="${y(v).toFixed(1)}" r="2.5" style="fill:var(--c${li + 1})"><title>${esc(labels[i])}: ${esc(fmt(v))}</title></circle>`).join("")}`).join("");
  const ax = labels.map((lb, i) => (labels.length > 8 && i % 2 ? "" : `<text class="ax" x="${x(i).toFixed(1)}" y="${H - 8}" text-anchor="middle">${esc(lb)}</text>`)).join("");
  const legend = lines.length > 1 ? `<div class="form-row" style="gap:14px;padding:0 4px 6px;font-size:12px">${lines.map((l, i) => `<span class="chip"><span class="sq" style="background:var(--c${i + 1})"></span>${esc(l.name)}</span>`).join("")}</div>` : "";
  return `<div class="xm-line"><svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Trend">${grid}${paths}${ax}</svg>${legend}</div>`;
}
const xmMonths = (n) => { const out = []; const t = todayStr(); let y = +t.slice(0, 4), m = +t.slice(5, 7); for (let i = 0; i < n; i++) { out.unshift(`${y}-${String(m).padStart(2, "0")}`); m--; if (!m) { m = 12; y--; } } return out; };
const xmNetOpen = (list) => list.reduce((t, i) => t + (i.totalCents || 0) - (i.paidCents || 0), 0);
const xmOpenBills = (a = A) => inScope(S.apInvoices).filter((i) => ["APPROVED", "PARTIALLY_PAID", "PENDING_APPROVAL"].includes(i.status));
const xmOpenInvoices = () => inScope(S.arInvoices).filter((i) => ["SENT", "APPROVED", "PARTIALLY_PAID"].includes(i.status));
function xmAging(list) {
  const t = todayStr(), b = [["Current", 0], ["1–30 days", 0], ["31–60 days", 0], ["61–90 days", 0], ["Over 90", 0]];
  for (const i of list) { const open = (i.totalCents || 0) - (i.paidCents || 0); if (open <= 0) continue; const days = Math.round((D(t) - D(i.dueDate)) / MS_DAY); const k = days <= 0 ? 0 : days <= 30 ? 1 : days <= 60 ? 2 : days <= 90 ? 3 : 4; b[k][1] += open; }
  return b.map(([label, v]) => ({ label, v, d: moneyCompact(v) }));
}
const xmAcct = (id) => byId(S.accounts, id);
function xmExpenseByAccount(range, ids) {
  const r = xmRangeDates(range), m = new Map();
  const jeOk = new Map(S.journalEntries.filter((j) => ids.includes(j.companyId) && j.status !== "VOID" && xmInRange(j.date, r)).map((j) => [j.id, j]));
  for (const l of S.journalLines) { if (!jeOk.has(l.journalEntryId)) continue; const a = xmAcct(l.accountId); if (!a || a.type !== "EXPENSE") continue; m.set(a.name, (m.get(a.name) || 0) + (l.debitCents || 0) - (l.creditCents || 0)); }
  return [...m].filter(([, v]) => v > 0).sort((x, y) => y[1] - x[1]).slice(0, 8).map(([label, v]) => ({ label, v, d: moneyCompact(v) }));
}
function xmMonthlyPL(ids, months) {
  const rev = Object.fromEntries(months.map((m) => [m, 0])), exp = { ...rev };
  const je = new Map(S.journalEntries.filter((j) => ids.includes(j.companyId) && j.status !== "VOID").map((j) => [j.id, j]));
  for (const l of S.journalLines) { const j = je.get(l.journalEntryId); if (!j) continue; const m = j.date.slice(0, 7); if (!(m in rev)) continue; const a = xmAcct(l.accountId); if (!a) continue; if (a.type === "REVENUE") rev[m] += (l.creditCents || 0) - (l.debitCents || 0); else if (a.type === "EXPENSE") exp[m] += (l.debitCents || 0) - (l.creditCents || 0); }
  return { labels: months.map((m) => MON[+m.slice(5, 7) - 1]), lines: [{ name: "Revenue", values: months.map((m) => Math.round(rev[m] / 100)) }, { name: "Expenses", values: months.map((m) => Math.round(exp[m] / 100)) }] };
}
