  "search-results": xmDef("Search Results", "Data", "A saved search, shown as a list — the same search as the top bar, limited to what this person may open.", "Global search", null, ["title", "q", "limit", "size"], { title: "Search", q: "", limit: "8" }, (c) => { if (!c.q) return xmCard(c.title, xmEmptyMsg("Enter a search term in the component settings.")); const groups = searchResults(c.q); const items = groups.flatMap(([g, list]) => list.map((x) => ({ ...x, g }))).slice(0, +c.limit || 8); return xmCard(`${c.title || "Search"} · “${c.q}”`, items.length ? `<ul class="xm-list">${items.map((x) => `<li data-go="${esc(x.go)}" style="cursor:pointer"><span><b>${esc(x.t)}</b><small>${esc(x.g)} · ${esc(x.s || "")}</small></span></li>`).join("")}</ul>` : xmEmptyMsg(`Nothing found for “${c.q}”.`)); }, "configurable"),
