  "timesheet-summary": xmDef("Timesheet Summary", "Time", "The current pay period: hours entered, status, days left — or, for a team, who has sent theirs in.", "Timesheets", "@employee", ["title", "scope", "size"], { title: "This pay period", scope: "user" }, (c) => { const e = A.employee, p = xmCurrentPeriod(e); if (c.scope === "user") { const s = S.timesheets.find((t) => t.employeeId === e.id && t.periodStart === p.start); const left = Math.max(0, Math.round((D(p.end) - D(todayStr())) / MS_DAY)); return xmCard(c.title, xmTiles([{ l: "Period", v: periodLabel(p.start, p.end).replace(/, \d{4}$/, ""), h: `${left} day${left === 1 ? "" : "s"} left` }, { l: "Hours entered", v: s ? hrs(s.workedHours) : "0.00", h: s ? xmStatusWord(s.status) : "Not started", go: "/me/time" }]), xmLink("/me/time", "My Time →")); } const emps = xmScopeEmps(c.scope).filter((x) => x.id !== e.id || c.scope !== "team"); const sent = emps.filter((x) => S.timesheets.some((t) => t.employeeId === x.id && t.periodStart === p.start && ["SUBMITTED", "APPROVED", "LOCKED"].includes(t.status))).length; return xmCard(c.title, xmTiles([{ l: "People", v: String(emps.length), h: xmScopeText(c.scope) }, { l: "Timesheets in", v: `${sent} / ${emps.length}`, h: periodLabel(p.start, p.end), go: can(A, "timesheets.view") ? "/hr/timesheets" : "/team" }]), can(A, "timesheets.view") ? xmLink("/hr/timesheets", "Timesheets →") : ""); }),
