  "expense-summary": xmDef("Expense Summary", "Finance", "Expense claims in the period: open, approved, paid back — for the person, a team or the company.", "Expense claims", ["expenses.view", "@employee"], ["title", "scope", "range", "size"], { title: "Expenses", scope: "user", range: "quarter" }, (c) => { const emps = new Set(xmScopeEmps(c.scope).map((e) => e.id)); const r = xmRangeDates(c.range); const l = inScope(S.expenseClaims).filter((x) => emps.has(x.employeeId) && (can(A, "expenses.view") || x.employeeId === A.employee?.id) && (c.range === "all" || xmInRange(x.createdAt, r))); const sum = (f) => l.filter(f).reduce((s, x) => s + (x.totalCents || 0), 0); return xmCard(c.title, xmTiles([{ l: "Claims", v: String(l.length), h: XM_RANGES.find((x) => x[0] === c.range)?.[1] || "" }, { l: "Waiting", v: moneyCompact(sum((x) => ["SUBMITTED", "PENDING_APPROVAL"].includes(x.status))), h: "For approval" }, { l: "Paid back", v: moneyCompact(sum((x) => x.status === "PAID" || x.status === "REIMBURSED")), h: "Reimbursed" }]), xmLink(can(A, "expenses.view") ? "/finance/expenses" : "/me/expenses", "Claims →")); }),
  "budget-summary": xmDef("Budget Summary", "Finance", "Budget versus posted spend for the fiscal year, by account.", "Budgets and the ledger", "budgets.view", ["title", "limit", "size"], { title: "Budget vs actual", limit: "8" }, (c) => { const ids = scopeIds(S, A); const yr = todayStr().slice(0, 4); const budgets = S.budgets.filter((b) => ids.includes(b.companyId) && String(b.fiscalYear) === yr); if (!budgets.length) return xmCard(c.title, xmEmptyMsg(`No budget for ${yr} in this scope.`), xmLink("/finance/budgets", "Budgets →")); const bl = new Map(); for (const l of S.budgetLines) if (budgets.some((b) => b.id === l.budgetId)) bl.set(l.accountId, (bl.get(l.accountId) || 0) + (l.amountCents || 0)); const actual = new Map(); const je = new Map(S.journalEntries.filter((j) => ids.includes(j.companyId) && j.date.startsWith(yr) && j.status !== "VOID").map((j) => [j.id, j])); for (const l of S.journalLines) if (je.has(l.journalEntryId) && bl.has(l.accountId)) actual.set(l.accountId, (actual.get(l.accountId) || 0) + (l.debitCents || 0) - (l.creditCents || 0)); const rows = [...bl].map(([acc, b]) => ({ name: xmAcct(acc)?.name || acc, b, a: actual.get(acc) || 0 })).sort((x, y) => y.b - x.b).slice(0, +c.limit || 8); return xmCard(c.title, `<div class="xm-bars">${rows.map((r) => `<div class="hbar"><span class="nm" title="${esc(r.name)}">${esc(r.name)}</span><span class="tr"><i style="width:${Math.min(100, Math.round((r.a / Math.max(1, r.b)) * 100))}%;background:${r.a > r.b ? "var(--bad)" : "var(--action)"}"></i></span><span class="num" style="font-size:12px;white-space:nowrap">${moneyCompact(r.a)} / ${moneyCompact(r.b)}</span></div>`).join("")}</div>`, xmLink("/finance/budgets", "Budgets →")); }),
  "payment-status": xmDef("Payment Status", "Finance", "Bills approved and waiting to be paid, paid this month, and deposits received.", "Payables and receivables", "ap.view", ["title", "size"], { title: "Payments" }, (c) => { const m = todayStr().slice(0, 7); const toPay = xmOpenBills().filter((i) => ["APPROVED", "PARTIALLY_PAID"].includes(i.status)); const paid = inScope(S.apInvoices).filter((i) => i.status === "PAID" && (i.paidAt || i.postedAt || "").startsWith(m)); const dep = can(A, "ar.view") ? inScope(S.arInvoices).filter((i) => i.status === "PAID" && (i.paidAt || i.postedAt || "").startsWith(m)) : []; return xmCard(c.title, xmTiles([{ l: "Ready to pay", v: moneyCompact(xmNetOpen(toPay)), h: `${toPay.length} approved bill${toPay.length === 1 ? "" : "s"}`, go: "/finance/ap/pay" }, { l: "Paid this month", v: moneyCompact(paid.reduce((s, i) => s + (i.totalCents || 0), 0)), h: `${paid.length} bill${paid.length === 1 ? "" : "s"}` }, ...(can(A, "ar.view") ? [{ l: "Received this month", v: moneyCompact(dep.reduce((s, i) => s + (i.totalCents || 0), 0)), h: `${dep.length} invoice${dep.length === 1 ? "" : "s"}`, go: "/finance/ar" }] : [])]), xmLink("/finance/ap", "Bills →")); }),
