  "birthdays": xmDef("Birthday / Anniversary", "HR", "Work anniversaries coming up (the platform keeps start dates, not birthdays).", "Employee records", ["hr.employees.view", "@employee"], ["title", "days", "scope", "size"], { title: "Work anniversaries", days: "60", scope: "company" }, (c) => { const t = todayStr(), yr = +t.slice(0, 4); const rows = xmScopeEmps(c.scope).map((e) => { if (!e.startDate) return null; const md = e.startDate.slice(5); let next = `${yr}-${md}`; if (next < t) next = `${yr + 1}-${md}`; const days = Math.round((D(next) - D(t)) / MS_DAY); const years = +next.slice(0, 4) - +e.startDate.slice(0, 4); return years > 0 && days <= (+c.days || 60) ? { t: empName(e), s: `${years} year${years === 1 ? "" : "s"} on ${dShort(next)}`, r: days === 0 ? "Today" : `in ${days} d`, days } : null; }).filter(Boolean).sort((a, b) => a.days - b.days); return xmCard(c.title, rows.length ? xmList(rows.slice(0, 8)) : xmEmptyMsg("No anniversaries in this window.")); }),
